{'code': "from qgis.PyQt.QtWidgets import QApplication, QDialog, QLabel, QLineEdit, QPlainTextEdit, QTextEdit
dlg = next((w for w in QApplication.topLevelWidgets() if isinstance(w, QDialog) and w.isVisible()), None)
texts = []
for child in dlg.findChildren((QLabel, QLineEdit, QPlainTextEdit, QTextEdit)):
    t = ''
    if hasattr(child, 'toPlainText'):
        t = child.toPlainText()
    elif hasattr(child, 'text'):
        t = child.text()
    if t and t.strip():
        texts.append({'cls': child.metaObject().className(), 'ro': getattr(child, 'isReadOnly', lambda: None)(), 'text': t})
result = {'title': dlg.windowTitle(), 'size': [dlg.width(), dlg.height()], 'fields': texts}"}
